/***************
 * @file level1.hpp
 * @brief AVX2 BLAS Level-1v物理内核
 ***************/

#include <immintrin.h>

#include <cstdint>
#include <type_traits>

/***************
 * @file avx2_float_storage.hpp
 * @brief AVX2浮点存储的八元素加载与存储转换
 ***************/

#include <immintrin.h>


namespace yt::blas {

template <typename Storage>
struct Avx2FloatStorage;

template <>
struct Avx2FloatStorage<float> {
    static constexpr bool available = true;

    static __m256 load(const float* values) {
        return _mm256_loadu_ps(values);
    }

    static void store(float* values, __m256 vector) {
        _mm256_storeu_ps(values, vector);
    }
};

template <>
struct Avx2FloatStorage<yt::float16> {
#if defined(__F16C__)
    static constexpr bool available = true;

    static __m256 load(const yt::float16* values) {
        return _mm256_cvtph_ps(_mm_loadu_si128(reinterpret_cast<const __m128i*>(values)));
    }

    static void store(yt::float16* values, __m256 vector) {
        __m128i converted = _mm256_cvtps_ph(vector, _MM_FROUND_TO_NEAREST_INT | _MM_FROUND_NO_EXC);
        _mm_storeu_si128(reinterpret_cast<__m128i*>(values), converted);
    }
#else
    static constexpr bool available = false;
#endif
};

}  // namespace yt::blas

namespace yt::blas {

/// @brief 计算rho = beta*rho + alpha*dot(x,y)
/// @details 步幅以元素计；FP16重载使用FP32累加。
/// @note 物理内核不分配内存、不创建线程，也不检查输入存储范围。
template <typename Storage>
    requires(std::is_same_v<Storage, float> || std::is_same_v<Storage, yt::float16>)
float dotxv(
    int n, float alpha, const Storage* x, int64_t incx, const Storage* y, int64_t incy, float beta, float rho
);

/// @brief 计算y = y + alpha*x
template <typename XStorage, typename YStorage>
    requires(
        (std::is_same_v<XStorage, float> && std::is_same_v<YStorage, float>) ||
        (std::is_same_v<XStorage, yt::float16> && std::is_same_v<YStorage, yt::float16>) ||
        (std::is_same_v<XStorage, yt::float16> && std::is_same_v<YStorage, float>)
    )
void axpyv(int n, float alpha, const XStorage* x, int64_t incx, YStorage* y, int64_t incy);

/// @brief 计算x = beta*x
template <typename Storage>
    requires(std::is_same_v<Storage, float> || std::is_same_v<Storage, yt::float16>)
void scalv(int n, float beta, Storage* x, int64_t incx);

/// @brief 将向量元素设置为指定值
template <typename Storage>
    requires(std::is_same_v<Storage, float> || std::is_same_v<Storage, yt::float16>)
void setv(int n, float value, Storage* x, int64_t incx);

}  // namespace yt::blas

/***************
 * file: blas/kernels/avx2/dotxv.inl
 * purpose: AVX2向量点积物理内核实现。
 ***************/

namespace yt::blas {

inline float avx2HorizontalSum(__m256 value) {
    __m128 low = _mm256_castps256_ps128(value);
    __m128 high = _mm256_extractf128_ps(value, 1);
    __m128 sum = _mm_add_ps(low, high);
    sum = _mm_hadd_ps(sum, sum);
    sum = _mm_hadd_ps(sum, sum);
    return _mm_cvtss_f32(sum);
}

template <typename Storage>
    requires(std::is_same_v<Storage, float> || std::is_same_v<Storage, yt::float16>)
inline float dotxv(
    int n, float alpha, const Storage* x, int64_t incx, const Storage* y, int64_t incy, float beta, float rho
) {
    float sum = 0.0f;
    if (n > 0 && alpha != 0.0f) {
        int i = 0;
        if constexpr (Avx2FloatStorage<Storage>::available) {
            if (incx == 1 && incy == 1) {
                __m256 acc0 = _mm256_setzero_ps();
                __m256 acc1 = _mm256_setzero_ps();
                __m256 acc2 = _mm256_setzero_ps();
                __m256 acc3 = _mm256_setzero_ps();
                for (; i + 32 <= n; i += 32) {
                    acc0 = _mm256_fmadd_ps(
                        Avx2FloatStorage<Storage>::load(x + i),
                        Avx2FloatStorage<Storage>::load(y + i),
                        acc0
                    );
                    acc1 = _mm256_fmadd_ps(
                        Avx2FloatStorage<Storage>::load(x + i + 8),
                        Avx2FloatStorage<Storage>::load(y + i + 8),
                        acc1
                    );
                    acc2 = _mm256_fmadd_ps(
                        Avx2FloatStorage<Storage>::load(x + i + 16),
                        Avx2FloatStorage<Storage>::load(y + i + 16),
                        acc2
                    );
                    acc3 = _mm256_fmadd_ps(
                        Avx2FloatStorage<Storage>::load(x + i + 24),
                        Avx2FloatStorage<Storage>::load(y + i + 24),
                        acc3
                    );
                }
                for (; i + 8 <= n; i += 8) {
                    acc0 = _mm256_fmadd_ps(
                        Avx2FloatStorage<Storage>::load(x + i),
                        Avx2FloatStorage<Storage>::load(y + i),
                        acc0
                    );
                }
                sum = avx2HorizontalSum(
                    _mm256_add_ps(_mm256_add_ps(acc0, acc1), _mm256_add_ps(acc2, acc3))
                );
            }
        }
        for (; i < n; ++i) {
            sum += static_cast<float>(x[i * incx]) * static_cast<float>(y[i * incy]);
        }
    }

    // beta为0时不读取rho，允许调用方传入未初始化的输出存储。
    return beta == 0.0f ? alpha * sum : beta * rho + alpha * sum;
}

}  // namespace yt::blas
/***************
 * file: blas/kernels/avx2/axpyv.inl
 * purpose: AVX2向量AXPY物理内核实现。
 ***************/

namespace yt::blas {

template <typename XStorage, typename YStorage>
    requires(
        (std::is_same_v<XStorage, float> && std::is_same_v<YStorage, float>) ||
        (std::is_same_v<XStorage, yt::float16> && std::is_same_v<YStorage, yt::float16>) ||
        (std::is_same_v<XStorage, yt::float16> && std::is_same_v<YStorage, float>)
    )
inline void axpyv(int n, float alpha, const XStorage* x, int64_t incx, YStorage* y, int64_t incy) {
    if (n <= 0 || alpha == 0.0f) return;

    int i = 0;
    if constexpr (Avx2FloatStorage<XStorage>::available && Avx2FloatStorage<YStorage>::available) {
        if (incx == 1 && incy == 1) {
            __m256 va = _mm256_set1_ps(alpha);
            for (; i + 8 <= n; i += 8) {
                __m256 result = _mm256_fmadd_ps(
                    va, Avx2FloatStorage<XStorage>::load(x + i), Avx2FloatStorage<YStorage>::load(y + i)
                );
                Avx2FloatStorage<YStorage>::store(y + i, result);
            }
        }
    }
    for (; i < n; ++i) {
        y[i * incy] = YStorage(
            static_cast<float>(y[i * incy]) + alpha * static_cast<float>(x[i * incx])
        );
    }
}

}  // namespace yt::blas
/***************
 * file: blas/kernels/avx2/setv.inl
 * purpose: AVX2向量赋值物理内核实现。
 ***************/

namespace yt::blas {

template <typename Storage>
    requires(std::is_same_v<Storage, float> || std::is_same_v<Storage, yt::float16>)
inline void setv(int n, float value, Storage* x, int64_t incx) {
    if (n <= 0) return;

    int i = 0;
    if constexpr (std::is_same_v<Storage, float>) {
        if (incx == 1) {
            __m256 vector = _mm256_set1_ps(value);
            for (; i + 8 <= n; i += 8) Avx2FloatStorage<Storage>::store(x + i, vector);
        }
    }
    Storage storedValue(value);
    for (; i < n; ++i) x[i * incx] = storedValue;
}

}  // namespace yt::blas
/***************
 * file: blas/kernels/avx2/scalv.inl
 * purpose: AVX2向量缩放物理内核实现。
 ***************/

namespace yt::blas {

template <typename Storage>
    requires(std::is_same_v<Storage, float> || std::is_same_v<Storage, yt::float16>)
inline void scalv(int n, float beta, Storage* x, int64_t incx) {
    if (beta == 0.0f) {
        setv(n, 0.0f, x, incx);
        return;
    }
    if (beta == 1.0f || n <= 0) return;

    int i = 0;
    if constexpr (Avx2FloatStorage<Storage>::available) {
        if (incx == 1) {
            __m256 vb = _mm256_set1_ps(beta);
            for (; i + 8 <= n; i += 8) {
                __m256 result = _mm256_mul_ps(vb, Avx2FloatStorage<Storage>::load(x + i));
                Avx2FloatStorage<Storage>::store(x + i, result);
            }
        }
    }
    for (; i < n; ++i) x[i * incx] = Storage(beta * static_cast<float>(x[i * incx]));
}

}  // namespace yt::blas

namespace yt::blas {

/// @brief 计算带元素步幅的FP32向量点积
/// @note 负步幅要求指针已经指向逻辑首元素；n小于等于0时返回0。
float sdot_stride(const float* x, const float* y, int n, int64_t incx, int64_t incy);

/// @brief 计算连续FP32向量点积
float sdot_contiguous(const float* x, const float* y, int n);

/// @brief 计算FP32向量点积
float sdot(const float* x, const float* y, int n, int64_t incx = 1, int64_t incy = 1);

/// @brief 计算FP16向量点积并使用FP32累加
float hdot(const yt::float16* x, const yt::float16* y, int n, int64_t incx = 1, int64_t incy = 1);

}  // namespace yt::blas

