/***************
 * @file level1f.hpp
 * @brief BLAS Level-1f融合向量操作
 ***************/


#if YT_USE_YBLAS
/***************
 * @file level1f.hpp
 * @brief AVX2 BLAS Level-1f物理内核
 ***************/


#include <type_traits>

namespace yt::blas {

/// @brief 融合计算多列点积
/// @details a(i,j)=a[i*rsa+j*csa]，计算y[j]=beta*y[j]+alpha*sum_i(x[i]*a(i,j))。
/// @note FP16重载将输入转换后累加到FP32输出；调用方负责线程划分。
template <typename Storage>
    requires(std::is_same_v<Storage, float> || std::is_same_v<Storage, yt::float16>)
void dotxf(
    const BlasContext& context, int n, int f, float alpha, const Storage* x, int64_t incx, const Storage* a,
    int64_t rsa, int64_t csa, float beta, float* y, int64_t incy
);

/// @brief 融合计算多向量AXPY
/// @details a(i,j)=a[i*rsa+j*csa]，计算y[i]+=alpha*sum_j(a(i,j)*x[j])。
template <typename Storage>
    requires(std::is_same_v<Storage, float> || std::is_same_v<Storage, yt::float16>)
void axpyf(
    const BlasContext& context, int n, int f, float alpha, const Storage* a, int64_t rsa, int64_t csa,
    const Storage* x, int64_t incx, float* y, int64_t incy
);

}  // namespace yt::blas

/***************
 * file: blas/kernels/avx2/dotxf.inl
 * purpose: AVX2融合多列点积物理内核实现。
 ***************/

namespace yt::blas {

template <typename Storage>
    requires(std::is_same_v<Storage, float> || std::is_same_v<Storage, yt::float16>)
inline void dotxf(
    const BlasContext& context, int n, int f, float alpha, const Storage* x, int64_t incx, const Storage* a,
    int64_t rsa, int64_t csa, float beta, float* y, int64_t incy
) {
    if (f <= 0) return;
    if (n <= 0 || alpha == 0.0f) {
        scalv(f, beta, y, incy);
        return;
    }

    if constexpr (Avx2FloatStorage<Storage>::available) {
        if (context.df == 4 && f == 4 && incx == 1 && rsa == 1) {
            __m256 acc0 = _mm256_setzero_ps();
            __m256 acc1 = _mm256_setzero_ps();
            __m256 acc2 = _mm256_setzero_ps();
            __m256 acc3 = _mm256_setzero_ps();
            int i = 0;
            const Storage* a0 = a;
            const Storage* a1 = a + csa;
            const Storage* a2 = a + 2 * csa;
            const Storage* a3 = a + 3 * csa;
            for (; i + 8 <= n; i += 8) {
                __m256 vx = Avx2FloatStorage<Storage>::load(x + i);
                acc0 = _mm256_fmadd_ps(vx, Avx2FloatStorage<Storage>::load(a0 + i), acc0);
                acc1 = _mm256_fmadd_ps(vx, Avx2FloatStorage<Storage>::load(a1 + i), acc1);
                acc2 = _mm256_fmadd_ps(vx, Avx2FloatStorage<Storage>::load(a2 + i), acc2);
                acc3 = _mm256_fmadd_ps(vx, Avx2FloatStorage<Storage>::load(a3 + i), acc3);
            }
            float sums[4] = {
                avx2HorizontalSum(acc0),
                avx2HorizontalSum(acc1),
                avx2HorizontalSum(acc2),
                avx2HorizontalSum(acc3)
            };
            for (; i < n; ++i) {
                float xv = static_cast<float>(x[i]);
                sums[0] += xv * static_cast<float>(a0[i]);
                sums[1] += xv * static_cast<float>(a1[i]);
                sums[2] += xv * static_cast<float>(a2[i]);
                sums[3] += xv * static_cast<float>(a3[i]);
            }
            for (int j = 0; j < 4; ++j) {
                // beta为0时不读取旧y，允许GEMV输出存储尚未初始化。
                y[j * incy] = beta == 0.0f ? alpha * sums[j] : beta * y[j * incy] + alpha * sums[j];
            }
            return;
        }
    }

    for (int j = 0; j < f; ++j) {
        float previous = beta == 0.0f ? 0.0f : y[j * incy];
        y[j * incy] = dotxv(n, alpha, x, incx, a + j * csa, rsa, beta, previous);
    }
}

}  // namespace yt::blas
/***************
 * file: blas/kernels/avx2/axpyf.inl
 * purpose: AVX2融合多向量AXPY物理内核实现。
 ***************/

namespace yt::blas {

template <typename Storage>
    requires(std::is_same_v<Storage, float> || std::is_same_v<Storage, yt::float16>)
inline void axpyf(
    const BlasContext& context, int n, int f, float alpha, const Storage* a, int64_t rsa, int64_t csa,
    const Storage* x, int64_t incx, float* y, int64_t incy
) {
    if (n <= 0 || f <= 0 || alpha == 0.0f) return;

    if constexpr (Avx2FloatStorage<Storage>::available) {
        if (context.af == 8 && f == 8 && rsa == 1 && incy == 1) {
            __m256 scales[8];
            for (int j = 0; j < 8; ++j) {
                scales[j] = _mm256_set1_ps(alpha * static_cast<float>(x[j * incx]));
            }
            int i = 0;
            for (; i + 8 <= n; i += 8) {
                __m256 vy = Avx2FloatStorage<float>::load(y + i);
                for (int j = 0; j < 8; ++j) {
                    vy = _mm256_fmadd_ps(scales[j], Avx2FloatStorage<Storage>::load(a + j * csa + i), vy);
                }
                Avx2FloatStorage<float>::store(y + i, vy);
            }
            for (; i < n; ++i) {
                float value = y[i];
                for (int j = 0; j < 8; ++j) {
                    value += alpha * static_cast<float>(x[j * incx]) * static_cast<float>(a[i + j * csa]);
                }
                y[i] = value;
            }
            return;
        }
    }

    for (int j = 0; j < f; ++j) {
        axpyv(n, alpha * static_cast<float>(x[j * incx]), a + j * csa, rsa, y, incy);
    }
}

}  // namespace yt::blas
#endif
/***************
 * @file level2.hpp
 * @brief BLAS Level-2矩阵向量操作
 ***************/

#include <cstdint>
#include <type_traits>
#include <vector>


#if YT_USE_YBLAS

namespace yt::blas {

/// @brief 使用typed storage计算行式GEMV，FP16输出使用FP32累加。
template <typename T>
void gemv_row(
    const T* x, const T* B, T* y, int n, int k, float alpha, float beta, int64_t incx, int64_t rsb,
    int64_t csb, int64_t incy, const BlasContext& context = defaultBlasContext()
);

/// @brief 使用typed storage计算列式GEMV，FP16输出使用FP32累加。
template <typename T>
void gemv_col(
    const T* A, const T* x, T* y, int m, int k, float alpha, float beta, int64_t rsa, int64_t csa,
    int64_t incx, int64_t incy, const BlasContext& context = defaultBlasContext()
);

/// @brief 使用typed storage计算GER，FP16输出使用FP32累加。
template <typename T>
void ger(
    int m, int n, float alpha, float beta, const T* x, int64_t incx, const T* y, int64_t incy, T* C,
    int64_t rsc, int64_t csc
);

/// @brief 计算y[n] = beta*y + alpha*x[k]*B[k,n]
/// @details 矩阵地址为base[row*rsb+col*csb]，所有步幅均以元素计。
void gemv_row_simd(
    const float* x, const float* B, float* y, int n, int k, float alpha, float beta, int64_t incx,
    int64_t rsb, int64_t csb, int64_t incy, const BlasContext& context = defaultBlasContext()
);

/// @brief 计算y[m] = beta*y + alpha*A[m,k]*x[k]
/// @details 矩阵地址为base[row*rsa+col*csa]，所有步幅均以元素计。
void gemv_col_simd(
    const float* A, const float* x, float* y, int m, int k, float alpha, float beta, int64_t rsa, int64_t csa,
    int64_t incx, int64_t incy, const BlasContext& context = defaultBlasContext()
);

/// @brief 计算C(i,j) = beta*C(i,j) + alpha*x(i)*y(j)
/// @note 该接口显式包含标准BLAS GER没有的beta参数。
void sger(
    int m, int n, float alpha, float beta, const float* x, int64_t incx, const float* y, int64_t incy,
    float* C, int64_t rsc, int64_t csc
);

void sger(int m, int n, float alpha, const float* x, const float* y, float* C, int lda);

/// @brief 计算FP16列式GEMV
/// @details 每个输出元素使用FP32累加，完成后转换回FP16。
void hgemv_col(
    const yt::float16* A, const yt::float16* x, yt::float16* y, int m, int k, float alpha, float beta,
    int64_t rsa, int64_t csa, int64_t incx, int64_t incy, const BlasContext& context = defaultBlasContext()
);

/// @brief 计算FP16行式GEMV
/// @details 每个输出元素使用FP32累加，完成后转换回FP16。
void hgemv_row(
    const yt::float16* x, const yt::float16* B, yt::float16* y, int n, int k, float alpha, float beta,
    int64_t incx, int64_t rsb, int64_t csb, int64_t incy, const BlasContext& context = defaultBlasContext()
);

void hgemv(
    const yt::float16* A, const yt::float16* x, yt::float16* y, int m, int k, float alpha = 1.0f,
    float beta = 0.0f
);

/// @brief 计算FP16 GER并使用FP32临时累加
void hger(
    int m, int n, float alpha, float beta, const yt::float16* x, int64_t incx, const yt::float16* y,
    int64_t incy, yt::float16* C, int64_t rsc, int64_t csc
);

void hger(int m, int n, float alpha, const yt::float16* x, const yt::float16* y, yt::float16* C, int lda);

}  // namespace yt::blas

/***************
 * file: blas/gemv_row.inl
 * purpose: typed行式GEMV实现。
 ***************/

namespace yt::blas {

template <typename T>
inline void gemv_row(
    const T* x, const T* B, T* y, int n, int k, float alpha, float beta, int64_t incx, int64_t rsb,
    int64_t csb, int64_t incy, const BlasContext& context
) {
    static_assert(std::is_same_v<T, float> || std::is_same_v<T, yt::float16>);
    if (n <= 0) return;

    if (rsb == 1) {
        int df = std::max(1, context.df);
#ifdef _OPENMP
#pragma omp parallel for schedule(static) num_threads(g_num_threads) if (g_num_threads > 1 && n >= 64)
#endif
        for (int j = 0; j < n; j += df) {
            int fuse = std::min(df, n - j);
            if constexpr (std::is_same_v<T, float>) {
                dotxf(context, k, fuse, alpha, x, incx, B + j * csb, rsb, csb, beta, y + j * incy, incy);
            } else {
                // dotxf快速实例最多融合四个输出，更大的df逐输出回退。
                float values[4] = {};
                if (fuse <= 4) {
                    if (beta != 0.0f) {
                        for (int jj = 0; jj < fuse; ++jj) {
                            values[jj] = static_cast<float>(y[(j + jj) * incy]);
                        }
                    }
                    dotxf(context, k, fuse, alpha, x, incx, B + j * csb, rsb, csb, beta, values, 1);
                    for (int jj = 0; jj < fuse; ++jj) y[(j + jj) * incy] = T(values[jj]);
                } else {
                    for (int jj = 0; jj < fuse; ++jj) {
                        float value = beta == 0.0f ? 0.0f : static_cast<float>(y[(j + jj) * incy]);
                        value = dotxv(k, alpha, x, incx, B + (j + jj) * csb, rsb, beta, value);
                        y[(j + jj) * incy] = T(value);
                    }
                }
            }
        }
        return;
    }

    constexpr int outputBlock = 256;
    int af = std::max(1, context.af);
    static thread_local std::vector<float> output;
    float* outputData;
    int64_t outputStride;
    if constexpr (std::is_same_v<T, float>) {
        outputData = y;
        outputStride = incy;
    } else {
        output.resize(static_cast<size_t>(n));
        outputData = output.data();
        outputStride = 1;
        if (beta == 0.0f) {
            setv(n, 0.0f, outputData, 1);
        } else {
            for (int j = 0; j < n; ++j) outputData[j] = static_cast<float>(y[j * incy]);
            scalv(n, beta, outputData, 1);
        }
    }

#ifdef _OPENMP
#pragma omp parallel for schedule(static) \
    num_threads(g_num_threads) if (g_num_threads > 1 && n >= outputBlock)
#endif
    for (int j0 = 0; j0 < n; j0 += outputBlock) {
        int width = std::min(outputBlock, n - j0);
        float* yBlock = outputData + j0 * outputStride;
        if constexpr (std::is_same_v<T, float>) scalv(width, beta, yBlock, outputStride);
        if (k <= 0 || alpha == 0.0f) continue;
        for (int p = 0; p < k; p += af) {
            int fuse = std::min(af, k - p);
            axpyf(
                context, width, fuse, alpha, B + p * rsb + j0 * csb, csb, rsb, x + p * incx, incx,
                yBlock, outputStride
            );
        }
    }

    if constexpr (std::is_same_v<T, yt::float16>) {
        for (int j = 0; j < n; ++j) y[j * incy] = T(outputData[j]);
    }
}

inline void gemv_row_simd(
    const float* x, const float* B, float* y, int n, int k, float alpha, float beta, int64_t incx,
    int64_t rsb, int64_t csb, int64_t incy, const BlasContext& context
) {
    gemv_row(x, B, y, n, k, alpha, beta, incx, rsb, csb, incy, context);
}

inline void hgemv_row(
    const yt::float16* x, const yt::float16* B, yt::float16* y, int n, int k, float alpha, float beta,
    int64_t incx, int64_t rsb, int64_t csb, int64_t incy, const BlasContext& context
) {
    gemv_row(x, B, y, n, k, alpha, beta, incx, rsb, csb, incy, context);
}

}  // namespace yt::blas
/***************
 * file: blas/gemv_col.inl
 * purpose: typed列式GEMV实现。
 ***************/

namespace yt::blas {

template <typename T>
inline void gemv_col(
    const T* A, const T* x, T* y, int m, int k, float alpha, float beta, int64_t rsa, int64_t csa,
    int64_t incx, int64_t incy, const BlasContext& context
) {
    static_assert(std::is_same_v<T, float> || std::is_same_v<T, yt::float16>);
    if (m <= 0) return;

    if (rsa == 1) {
        constexpr int outputBlock = 256;
        int af = std::max(1, context.af);
        static thread_local std::vector<float> output;
        float* outputData;
        int64_t outputStride;
        if constexpr (std::is_same_v<T, float>) {
            outputData = y;
            outputStride = incy;
        } else {
            output.resize(static_cast<size_t>(m));
            outputData = output.data();
            outputStride = 1;
            if (beta == 0.0f) {
                setv(m, 0.0f, outputData, 1);
            } else {
                for (int i = 0; i < m; ++i) outputData[i] = static_cast<float>(y[i * incy]);
                scalv(m, beta, outputData, 1);
            }
        }

#ifdef _OPENMP
#pragma omp parallel for schedule(static) \
    num_threads(g_num_threads) if (g_num_threads > 1 && m >= outputBlock)
#endif
        for (int i0 = 0; i0 < m; i0 += outputBlock) {
            int height = std::min(outputBlock, m - i0);
            float* yBlock = outputData + i0 * outputStride;
            if constexpr (std::is_same_v<T, float>) scalv(height, beta, yBlock, outputStride);
            for (int p = 0; p < k; p += af) {
                int fuse = std::min(af, k - p);
                axpyf(
                    context, height, fuse, alpha, A + i0 * rsa + p * csa, rsa, csa, x + p * incx, incx,
                    yBlock, outputStride
                );
            }
        }

        if constexpr (std::is_same_v<T, yt::float16>) {
            for (int i = 0; i < m; ++i) y[i * incy] = T(outputData[i]);
        }
        return;
    }

    int df = std::max(1, context.df);
#ifdef _OPENMP
#pragma omp parallel for schedule(static) num_threads(g_num_threads) if (g_num_threads > 1 && m >= 128)
#endif
    for (int i = 0; i < m; i += df) {
        int fuse = std::min(df, m - i);
        if constexpr (std::is_same_v<T, float>) {
            dotxf(context, k, fuse, alpha, x, incx, A + i * rsa, csa, rsa, beta, y + i * incy, incy);
        } else {
            // dotxf快速实例最多融合四个输出，更大的df逐输出回退。
            float values[4] = {};
            if (fuse <= 4) {
                if (beta != 0.0f) {
                    for (int j = 0; j < fuse; ++j) {
                        values[j] = static_cast<float>(y[(i + j) * incy]);
                    }
                }
                dotxf(context, k, fuse, alpha, x, incx, A + i * rsa, csa, rsa, beta, values, 1);
                for (int j = 0; j < fuse; ++j) y[(i + j) * incy] = T(values[j]);
            } else {
                for (int j = 0; j < fuse; ++j) {
                    float value = beta == 0.0f ? 0.0f : static_cast<float>(y[(i + j) * incy]);
                    value = dotxv(k, alpha, x, incx, A + (i + j) * rsa, csa, beta, value);
                    y[(i + j) * incy] = T(value);
                }
            }
        }
    }
}

inline void gemv_col_simd(
    const float* A, const float* x, float* y, int m, int k, float alpha, float beta, int64_t rsa, int64_t csa,
    int64_t incx, int64_t incy, const BlasContext& context
) {
    gemv_col(A, x, y, m, k, alpha, beta, rsa, csa, incx, incy, context);
}

inline void hgemv_col(
    const yt::float16* A, const yt::float16* x, yt::float16* y, int m, int k, float alpha, float beta,
    int64_t rsa, int64_t csa, int64_t incx, int64_t incy, const BlasContext& context
) {
    gemv_col(A, x, y, m, k, alpha, beta, rsa, csa, incx, incy, context);
}

inline void hgemv(
    const yt::float16* A, const yt::float16* x, yt::float16* y, int m, int k, float alpha, float beta
) {
    gemv_col(A, x, y, m, k, alpha, beta, k, 1, 1, 1);
}

}  // namespace yt::blas
/***************
 * file: blas/ger.inl
 * purpose: typed GER实现。
 ***************/

namespace yt::blas {

template <typename T>
inline void ger(
    int m, int n, float alpha, float beta, const T* x, int64_t incx, const T* y, int64_t incy, T* C,
    int64_t rsc, int64_t csc
) {
    static_assert(std::is_same_v<T, float> || std::is_same_v<T, yt::float16>);
    if (m <= 0 || n <= 0) return;

    if (csc == 1 || std::is_same_v<T, yt::float16>) {
        if constexpr (std::is_same_v<T, float>) {
            for (int i = 0; i < m; ++i) {
                T* row = C + i * rsc;
                scalv(n, beta, row, csc);
                axpyv(n, alpha * x[i * incx], y, incy, row, csc);
            }
        } else {
            static thread_local std::vector<float> output;
            output.resize(static_cast<size_t>(n));
            for (int i = 0; i < m; ++i) {
                for (int j = 0; j < n; ++j) output[j] = static_cast<float>(C[i * rsc + j * csc]);
                scalv(n, beta, output.data(), 1);
                axpyv(n, alpha * static_cast<float>(x[i * incx]), y, incy, output.data(), 1);
                for (int j = 0; j < n; ++j) C[i * rsc + j * csc] = T(output[j]);
            }
        }
        return;
    }

    if constexpr (std::is_same_v<T, float>) {
        for (int j = 0; j < n; ++j) {
            T* column = C + j * csc;
            scalv(m, beta, column, rsc);
            axpyv(m, alpha * y[j * incy], x, incx, column, rsc);
        }
    } else {
        static thread_local std::vector<float> output;
        output.resize(static_cast<size_t>(m));
        for (int j = 0; j < n; ++j) {
            for (int i = 0; i < m; ++i) output[i] = static_cast<float>(C[i * rsc + j * csc]);
            scalv(m, beta, output.data(), 1);
            axpyv(m, alpha * static_cast<float>(y[j * incy]), x, incx, output.data(), 1);
            for (int i = 0; i < m; ++i) C[i * rsc + j * csc] = T(output[i]);
        }
    }
}

inline void sger(
    int m, int n, float alpha, float beta, const float* x, int64_t incx, const float* y, int64_t incy,
    float* C, int64_t rsc, int64_t csc
) {
    ger(m, n, alpha, beta, x, incx, y, incy, C, rsc, csc);
}

inline void sger(int m, int n, float alpha, const float* x, const float* y, float* C, int lda) {
    ger(m, n, alpha, 1.0f, x, 1, y, 1, C, lda, 1);
}

inline void hger(
    int m, int n, float alpha, float beta, const yt::float16* x, int64_t incx, const yt::float16* y,
    int64_t incy, yt::float16* C, int64_t rsc, int64_t csc
) {
    ger(m, n, alpha, beta, x, incx, y, incy, C, rsc, csc);
}

inline void hger(
    int m, int n, float alpha, const yt::float16* x, const yt::float16* y, yt::float16* C, int lda
) {
    ger(m, n, alpha, 1.0f, x, 1, y, 1, C, lda, 1);
}

}  // namespace yt::blas
#endif  // YT_USE_YBLAS
