/***************
 * @file broadcast.hpp
 * @brief 广播操作函数声明
 ***************/

#include <array>
#include <bit>
#include <cstddef>
#include <cstdint>
#include <limits>
#include <stdexcept>
#include <tuple>
#include <type_traits>
#include <utility>
#include <vector>


namespace yt::strided {

/// @brief 计算多个shape统一广播后的结果shape。
/// @throws std::runtime_error 输入shape无法广播时抛出。
std::vector<int> computeBroadcastShape(const std::vector<std::vector<int>>& shapes);

/// @brief 编译期计算参数包中张量类型的数量
/// @tparam Args 参数类型包
/// @return 张量参数的数量
template <typename... Args>
constexpr size_t countTensors();

/// @brief 使用模板递归在编译期展开N个索引的累加
/// @tparam N 张量数量
/// @tparam I 当前处理的张量索引
template <size_t N, size_t I = 0>
struct IndexAccumulator {
    template <typename StridesArray, typename IndicesArray>
    static inline void accumulate(IndicesArray& indices, int posi, const StridesArray& strides, int dimIdx);
};

/// @brief 编译期展开的N元索引计算器（使用编译期dim）
/// @tparam N 张量数量
/// @tparam Dim 维度（编译期常量）
template <size_t N, int Dim>
struct NaryIndexComputer {
    /// @brief 计算N个张量的数据索引
    /// @param index 线性索引
    /// @param logicStride 逻辑stride数组
    /// @param shape 广播shape数组
    /// @param strides N个张量的stride数组，每个是Dim维的数组
    /// @return 包含N个数据索引的数组
    template <typename LogicStrideArray, typename ShapeArray, typename StridesArray>
    static inline std::array<int, N> compute(
        int index, const LogicStrideArray& logicStride, const ShapeArray& shape, const StridesArray& strides
    );

    /// @brief 同时计算this和N个其他张量的数据索引
    /// @param index 线性索引
    /// @param logicStride 逻辑stride数组
    /// @param shape 广播shape数组
    /// @param thisStride this的stride数组
    /// @param strides N个张量的stride数组
    /// @param thisDataIdx 输出：this的数据索引
    /// @return 包含N个数据索引的数组
    template <typename LogicStrideArray, typename ShapeArray, typename ThisStrideArray, typename StridesArray>
    static inline std::array<int, N> computeWithThis(
        int index, const LogicStrideArray& logicStride, const ShapeArray& shape,
        const ThisStrideArray& thisStride, const StridesArray& strides, int& thisDataIdx
    );

   private:
    template <size_t I, typename IndicesArray, typename StridesArray>
    static inline void accumulateAll(
        IndicesArray& indices, int posi, const StridesArray& strides, int dimIdx
    );
};

/// @brief 计算广播索引（运行时ndim版本）
/// @param index 线性索引
/// @param logicStride 逻辑stride
/// @param shape 广播shape
/// @param thisStride this张量的stride
/// @param otherStrides 其他张量的stride数组
/// @param thisIdx 输出：this的数据索引
/// @param otherIndices 输出：其他张量的数据索引
/// @param ndim 维度数
void computeBroadcastIndicesRuntime(
    int index, const std::vector<int>& logicStride, const std::vector<int>& shape,
    const std::vector<int>& thisStride, const std::vector<std::vector<int>>& otherStrides, int& thisIdx,
    std::vector<int>& otherIndices, int ndim
);

/// @brief 计算N个张量的广播索引（编译期展开）
/// @tparam N 张量数量
/// @param index 线性索引
/// @param logicStride 逻辑stride
/// @param broadcastShape 广播shape
/// @param strides 每个张量的广播stride数组
/// @param opdim 操作维度
/// @return 包含N个数据索引的数组
template <size_t N>
std::array<int, N> computeBroadcastIndices(
    int index, const std::vector<int>& logicStride, const std::vector<int>& broadcastShape,
    const std::array<const int*, N>& strides, int opdim
);

/// @brief 获取张量在广播shape下的stride
/// @param shape 原始张量的shape
/// @param stride 原始张量的stride
/// @param broadcastShape 广播后的shape
/// @return 广播stride（对于被广播的维度，stride为0）
std::vector<int> getBroadcastStride(
    const std::vector<int>& shape, const std::vector<int>& stride, const std::vector<int>& broadcastShape
);

/// @brief 计算张量在给定索引处的实际数据索引
/// @param linearIndex 线性索引
/// @param logicStride 逻辑stride（连续存储）
/// @param broadcastStride 广播stride
/// @param broadcastShape 广播shape
/// @return 实际数据索引
int computeDataIndex(
    int linearIndex, const std::vector<int>& logicStride, const std::vector<int>& broadcastStride,
    const std::vector<int>& broadcastShape
);

/// @brief 统一的广播操作函数（非原地），支持N元张量/标量操作
/// @tparam resultDim 结果张量维度。当所有张量参数不包含YTensorBase时可省略（自动推导）；
/// @tparam Func 函数类型，签名为 ReturnType func(const T&, const T&, ...) 或 ReturnType func(T, T, ...)
/// @tparam Args 参数类型，可以是YTensor、YTensorBase或标量（可转换为func参数类型）
/// @param func 操作函数，返回类型用于推断结果张量的标量类型
/// @param tensors 输入的张量或标量
/// @return 返回结果张量 YTensor<ReturnType, resultDim>，形状为所有输入张量广播后的形状
template <int _resultDim = -1, typename Func, typename... Args>
auto broadcast(Func&& func, Args&&... tensors);

/// @brief 统一的广播原地操作函数，支持N元张量/标量操作
/// @tparam TensorType 目标张量类型（YTensor<T, dim>）
/// @tparam Func 函数类型，签名为 void func(T&, const T&, ...) 或返回值被忽略
/// @tparam Args 参数类型，可以是YTensor或标量（可转换为func参数类型）
/// @param target 目标张量（将被原地修改）
/// @param func 操作函数，第一个参数为target的元素引用
/// @param tensors 输入的张量或标量
/// @return 返回target的引用
template <typename TensorType, typename Func, typename... Args>
TensorType& broadcastInplace(TensorType& target, Func&& func, Args&&... tensors);

/// @brief 运行时broadcast：返回YTensorBase的广播函数
/// @details 当输入参数中包含YTensorBase（非模板YTensor）时使用此版本，
///          因为输出维度在编译期无法确定，必须返回YTensorBase
/// @tparam ScalarT 标量类型（从func推断）
/// @tparam Func 函数类型
/// @tparam Args 参数类型（可以是YTensor/YTensorBase或可转换为ScalarT的值）
/// @param func 操作函数
/// @param tensors 输入的张量或标量
/// @return YTensorBase结果
/// @note 参数Args中每个类型必须是YTensor/YTensorBase或可转换为标量类型的值
template <typename Func, typename... Args>
yt::YTensorBase broadcastBase(Func&& func, Args&&... tensors);

/// @brief 对 runtime target 执行 callable 驱动的原地广播。
/// @details target 必须具有广播结果 shape；与 target 物理跨度重叠的 tensor 参数会先快照，
///          防止原地写入污染后续读取。
/// @tparam Func 首个参数为目标元素引用的 callable 类型
/// @tparam Args YTensor/YTensorBase 或可转换为 callable 标量类型的参数
/// @return target 的引用
template <typename Func, typename... Args>
yt::YTensorBase& broadcastInplaceBase(yt::YTensorBase& target, Func&& func, Args&&... tensors);

/// @brief 通过统一runtime broadcast kernel计算结果张量。
/// @param op broadcast运算类型。
/// @param inputs 参与广播的输入张量，dtype必须一致。
/// @param outputDtype 输出张量dtype；比较操作使用bool。
YTensorBase broadcast(
    yt::type::YBroadcastOp op, const std::vector<const YTensorBase*>& inputs, const std::string& outputDtype
);

/// @brief 将统一runtime broadcast结果写入已有输出张量（原地变体）。
/// @note output的shape必须与inputs广播结果一致。
/// @details 通过 YDTypeKernels::broadcastInplace 派发到具体dtype实现。
YTensorBase& broadcast_(
    yt::type::YBroadcastOp op, YTensorBase& output, const std::vector<const YTensorBase*>& inputs
);

/// @brief 将标量转换成与目标张量dtype一致的rank-0张量。
/// @tparam Scalar 标量类型
/// @param tensor 用于参考dtype的目标张量
/// @param scalar 输入标量
/// @return rank-0 YTensorBase，dtype与tensor一致
template <typename Scalar>
YTensorBase scalarTensor(const YTensorBase& tensor, const Scalar& scalar);

/// @brief 对 typed tensor 的每个逻辑元素调用 func，并原地保存结果。
/// @details func 可接收 `T&`，或接收 `T&` 与逻辑坐标；重叠 view 使用确定性的串行写入。
/// @param flop 非零时允许对 disjoint tensor 启用并行执行
template <typename T, int dim, typename Func>
YTensor<T, dim>& forEach(YTensor<T, dim>& tensor, Func&& func, double flop);

/// @brief 将 typed tensor 的每个逻辑元素原地设置为 value。
/// @note 对重叠 view 只遍历其逻辑映射，不假设底层 storage disjoint。
template <typename T, int dim>
YTensor<T, dim>& fill(YTensor<T, dim>& tensor, const T& value);

}  // namespace yt::strided
/***************
 * @file: strided/view.hpp
 * @brief: strided layout 的 view 类职责入口。
 ***************/

#include <algorithm>
#include <cstddef>
#include <vector>

namespace yt {
class YTensorBase;
template <typename T, int dim>
class YTensor;
}  // namespace yt

namespace yt::strided {

/// @brief 返回strided张量的逻辑shape。
std::vector<int> shape(const YTensorBase& tensor);
/// @brief 返回指定逻辑维度的长度，维度支持循环索引。
int shape(const YTensorBase& tensor, int dim);
/// @brief 返回由shape计算出的连续逻辑stride。
std::vector<int> logicalStride(const YTensorBase& tensor);
/// @brief 返回当前view实际访问storage时使用的物理stride。
std::vector<int> physicalStride(const YTensorBase& tensor);
/// @brief 返回指定维度的逻辑stride。
int logicalStride(const YTensorBase& tensor, int dim);
/// @brief 返回指定维度的物理stride。
int physicalStride(const YTensorBase& tensor, int dim);
/// @brief 返回逻辑元素数量，标量shape的size为1。
size_t size(const YTensorBase& tensor);
/// @brief 返回逻辑维度数量。
int ndim(const YTensorBase& tensor);
/// @brief 判断指定半开维度区间是否连续。
bool isContiguous(const YTensorBase& tensor, int fromDim, int toDim);
/// @brief 返回指定区间中连续尾部开始的维度。
int isContiguousFrom(const YTensorBase& tensor, int fromDim, int toDim);
/// @brief 判断不同逻辑坐标是否映射到不同storage位置。
bool isDisjoint(const YTensorBase& tensor);
/// @brief 判断两个view实际触及的storage字节跨度是否可能重叠。
bool physicalSpansOverlap(const YTensorBase& left, const YTensorBase& right);
/// @brief 按YTensor多负维度规则补全shape，并保证元素数量不变。
std::vector<int> autoShape(const YTensorBase& tensor, const std::vector<int>& shape);

/// @brief 创建共享storage的slice view。
/// @note start/end使用YTensor循环索引和autoFix语义；负step从区间末端反向访问。
YTensorBase slice(
    const YTensorBase& tensor, int atDim, int start = 0, int end = 0, int step = 1, bool autoFix = true
);
/// @brief 原地替换为slice view，不复制storage。
YTensorBase& slice_(
    YTensorBase& tensor, int atDim, int start = 0, int end = 0, int step = 1, bool autoFix = true
);
/// @brief 按维度顺序创建共享storage的permute view。
YTensorBase permute(const YTensorBase& tensor, const std::vector<int>& newOrder);
/// @brief 原地更新为permute view。
YTensorBase& permute_(YTensorBase& tensor, const std::vector<int>& newOrder);
/// @brief 交换两个维度并返回共享storage的view。
YTensorBase transpose(const YTensorBase& tensor, int dim0 = -2, int dim1 = -1);
/// @brief 为连续张量创建元素数量相同的新shape view。
YTensorBase view(const YTensorBase& tensor, const std::vector<int>& newShape);
/// @brief 必要时先连续化，再创建指定shape的张量。
YTensorBase reshape(const YTensorBase& tensor, const std::vector<int>& newShape);
/// @brief 插入长度为1的维度并返回共享storage的view。
YTensorBase unsqueeze(const YTensorBase& tensor, int dim);
/// @brief 原地插入长度为1的维度。
YTensorBase& unsqueeze_(YTensorBase& tensor, int dim);
/// @brief 删除指定singleton维度；默认删除全部singleton维度。
YTensorBase squeeze(const YTensorBase& tensor, int dim = -1);
/// @brief 原地删除singleton维度。
YTensorBase& squeeze_(YTensorBase& tensor, int dim = -1);
/// @brief 使用zero stride扩展singleton维度并返回共享storage的view。
YTensorBase repeat(const YTensorBase& tensor, const std::vector<int>& times);
/// @brief 原地使用zero stride扩展singleton维度。
YTensorBase& repeat_(YTensorBase& tensor, const std::vector<int>& times);
/// @brief 插入滑动窗口维度并返回共享storage的view。
YTensorBase unfold(const YTensorBase& tensor, int atDim, int kernel, int stride = 1, int dilation = 1);
/// @brief 原地插入滑动窗口维度。
YTensorBase& unfold_(YTensorBase& tensor, int atDim, int kernel, int stride = 1, int dilation = 1);
/// @brief 按物理stride重排维度，并将负stride归一化为正stride view。
YTensorBase mostContinuousView(const YTensorBase& tensor);
/// @brief 将逻辑坐标转换为连续逻辑索引。
size_t logicalIndex(const YTensorBase& tensor, const std::vector<int>& position);
/// @brief 将逻辑坐标转换为相对当前view起点的有符号物理偏移。
int relativeOffset(const YTensorBase& tensor, const std::vector<int>& position);
/// @brief 将连续逻辑索引转换为相对data指针的有符号物理偏移。
std::ptrdiff_t relativeOffset(const YTensorBase& tensor, size_t logicalIndex);
/// @brief 将逻辑坐标转换为相对storage起点的绝对物理偏移。
int storageOffset(const YTensorBase& tensor, const std::vector<int>& position);
/// @brief 将逻辑坐标转换为相对data指针的物理索引。
size_t physicalIndex(const YTensorBase& tensor, const std::vector<int>& position);
/// @brief 将连续逻辑索引转换为相对data指针的物理索引。
size_t physicalIndex(const YTensorBase& tensor, size_t logicalIndex);
/// @brief 将连续逻辑索引转换为storage起点的绝对元素索引，并验证storage边界。
size_t storageIndex(const YTensorBase& tensor, size_t logicalIndex);
/// @brief 将连续逻辑索引转换为逻辑坐标。
std::vector<int> coordinate(const YTensorBase& tensor, size_t index);
/// @brief 按给定长度拆分axis，返回共享原storage的slice views。
std::vector<YTensorBase> split(const YTensorBase& tensor, const std::vector<int>& splitSizes, int axis);
/// @brief 将axis等分为指定份数，返回共享原storage的slice views。
std::vector<YTensorBase> split(const YTensorBase& tensor, int parts, int axis);

/// @brief 将最后两个维度包装为runtime二维矩阵view元素。
/// @note 外层 tensor 拥有 YTensorBase wrapper 对象；每个 wrapper 与输入 tensor 共享 values storage。
YTensorBase matView(const YTensorBase& tensor);

/// @brief typed版本的矩阵view，保留元素类型和编译期batch维度。
/// @note 外层 tensor 管理 wrapper 生命周期，内层矩阵 view 与输入 tensor 共享 values storage。
template <typename T, int dim>
YTensor<YTensor<T, 2>, std::max(1, dim - 2)> matView(const YTensor<T, dim>& tensor);

#if YT_USE_EIGEN
/// @brief 为batch tensor创建Eigen矩阵view张量。
/// @warning Eigen::Map 只借用输入 storage 的裸指针；使用返回值期间输入 storage 必须保持存活且不得被替换。
template <typename T, int dim>
auto matViewEigen(const YTensor<T, dim>& tensor) requires(dim > 2);

/// @brief 为一维或二维tensor创建单个Eigen矩阵view。
/// @warning Eigen::Map 只借用输入 storage 的裸指针；使用返回值期间输入 storage 必须保持存活且不得被替换。
template <typename T, int dim>
auto matViewEigen(const YTensor<T, dim>& tensor) requires(dim <= 2);
#endif

}  // namespace yt::strided
